import { tags } from "typia";

/**
 * High-level aggregated counts surfaced to admins. All counts exclude
 * soft-deleted records (rows where deleted_at IS NOT NULL) and are non-negative
 * integers representing current persisted state at the time of computation.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ITodoAppAdminTotals = {
  /**
   * Total number of registered users in the system. Excludes soft-deleted
   * user accounts (deleted_at IS NOT NULL).
   */
  total_users: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of unique users active within the reporting window. Calculated
   * from activity logs and excludes soft-deleted accounts.
   */
  active_users: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of accounts currently suspended (administrative suspension state).
   * Excludes accounts already purged or hard-deleted.
   */
  suspended_accounts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of todo lists in the system. Excludes soft-deleted lists
   * (deleted_at IS NOT NULL).
   */
  total_lists: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of lists with visibility set to 'public'. Excludes soft-deleted
   * lists.
   */
  public_lists: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of lists with visibility set to 'private' or 'shared-invite-only'.
   * Excludes soft-deleted lists.
   */
  private_lists: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of invitations currently in 'pending' state (awaiting acceptance,
   * not expired). Excludes soft-deleted invitation rows.
   */
  pending_invitations: number & tags.Type<"int32"> & tags.Minimum<0>;
};
